// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;

    // The owner of C is this test contract; give it a receive() so ETH transfers to it succeed.
    receive() external payable {}

    function setUp() public {
        c = new SimpleWallet();
    }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 1 && amount < type(uint128).max);

        // deposit: a third party sends `amount` wei to C's fallback
        address depositor = address(0xBEEF);
        vm.deal(depositor, amount);
        vm.prank(depositor);
        (bool sent,) = address(c).call{value: amount}("");
        assertTrue(sent, "deposit must succeed");

        uint256 balanceBefore = address(c).balance;
        vm.assume(balanceBefore == amount);

        // owner drains everything
        c.withdrawAll();

        assertTrue(address(c).balance == 0, "withdrawAll must drain full balance");
    }
}
